1	package com.example.starter.service;
2	
3	import java.math.BigDecimal;
4	import java.sql.ResultSet;
5	import java.sql.SQLException;
6	import java.sql.Timestamp;
7	import java.time.Duration;
8	import java.time.Instant;
9	import java.time.LocalDateTime;
10	import java.time.ZoneId;
11	import java.time.ZoneOffset;
12	import java.util.List;
13	import java.util.Optional;
14	
15	import com.example.starter.dto.GrainDtos.ApplyFumigationRequest;
16	import com.example.starter.dto.GrainDtos.ApproveFumigationRequest;
17	import com.example.starter.dto.GrainDtos.BeginAerationRequest;
18	import com.example.starter.dto.GrainDtos.FumigationView;
19	import com.example.starter.dto.GrainDtos.GasReadingRequest;
20	import com.example.starter.dto.GrainDtos.GasReadingView;
21	import com.example.starter.dto.GrainDtos.ReleaseFumigationRequest;
22	import com.example.starter.dto.GrainDtos.ReleaseView;
23	import com.example.starter.dto.GrainDtos.StartFumigationRequest;
24	import com.example.starter.error.ApiException;
25	import com.example.starter.model.FumigationStatus;
26	import com.example.starter.model.SiloStatus;
27	import com.example.starter.util.Fingerprints;
28	
29	import org.springframework.dao.DuplicateKeyException;
30	import org.springframework.jdbc.core.JdbcTemplate;
31	import org.springframework.stereotype.Service;
32	import org.springframework.transaction.annotation.Transactional;
33	
34	/**
35	 * 熏蒸作业服务：申请（UTC 作业窗、与普通通风窗半开互斥）、两名不同审批人双审批、
36	 * 实际开始原子锁仓并冻结方案版本、结束转散气原子占用空闲风机、合成气体采样
37	 * （单号内序号唯一、时刻严格递增）、两名不同复核人重查最新读数与版本后原子解除。
38	 *
39	 * <p>版本从 1 开始，每次成功变更加 1；写操作均带 requestId 幂等，
40	 * 指纹为 requestId 与全部业务参数（含版本、集合、精确时刻）的结构化 SHA-256，
41	 * 同键同参重放首次冻结结果，同键异参 409，业务失败回滚不占键。
42	 */
43	@Service
44	public class FumigationService {
45	
46	    /** 解除所需连续安全点数。 */
47	    static final int SAFE_RUN_LENGTH = 3;
48	    /** 连续安全三点首末最小间隔，恰等合法。 */
49	    static final Duration MIN_FIRST_LAST_GAP = Duration.ofMinutes(30);
50	
51	    private final JdbcTemplate jdbc;
52	    private final SiloService siloService;
53	
54	    public FumigationService(JdbcTemplate jdbc, SiloService siloService) {
55	        this.jdbc = jdbc;
56	        this.siloService = siloService;
57	    }
58	
59	    /**
60	     * 申请熏蒸单：绑定粮仓与 UTC 半开作业窗；同仓作业窗与普通通风窗及未终结熏蒸窗
61	     * 半开互斥（端点相接可共存）；同仓只允许一张未终结熏蒸单。
62	     */
63	    @Transactional
64	    public FumigationView apply(long siloId, ApplyFumigationRequest request) {
65	        if (!request.windowStart().isBefore(request.windowEnd())) {
66	            throw ApiException.badRequest("INVALID_WINDOW", "作业窗起点必须早于终点");
67	        }
68	        if (request.safetyThreshold().signum() < 0) {
69	            throw ApiException.badRequest("INVALID_THRESHOLD", "合成安全阈值必须为非负小数");
70	        }
71	        String fingerprint = Fingerprints.structured(request.requestId(), siloId,
72	                request.windowStart(), request.windowEnd(), request.syntheticAgent(),
73	                request.safetyThreshold().stripTrailingZeros().toPlainString());
74	
75	        Optional<OrderRow> existing = findOrderByColumn("request_id", request.requestId());
76	        if (existing.isPresent()) {
77	            return replayOrConflict(existing.get(), fingerprint);
78	        }
79	
80	        // 锁定粮仓行，串行化同仓并发申请
81	        lockSilo(siloId);
82	
83	        Optional<OrderRow> rechecked = findOrderByColumn("request_id", request.requestId());
84	        if (rechecked.isPresent()) {
85	            return replayOrConflict(rechecked.get(), fingerprint);
86	        }
87	
88	        SiloStatus siloStatus = currentSiloStatus(siloId);
89	        if (siloStatus == SiloStatus.ARCHIVED) {
90	            throw ApiException.conflict("SILO_ARCHIVED", "粮仓已归档，禁止申请熏蒸");
91	        }
92	        if (siloStatus == SiloStatus.MANUAL_HANDLING) {
93	            throw ApiException.unprocessable("MANUAL_HANDLING_REQUIRED", "粮仓已转人工处置，禁止申请熏蒸");
94	        }
95	        if (siloStatus == SiloStatus.FUMIGATING || siloStatus == SiloStatus.AERATING) {
96	            throw ApiException.conflict("FUMIGATION_ALREADY_ACTIVE", "粮仓熏蒸锁仓中，禁止再申请熏蒸");
97	        }
98	
99	        assertNoWindowOverlap(siloId, request.windowStart(), request.windowEnd());
100	
101	        long orderId;
102	        try {
103	            orderId = siloService.insert(
104	                    "INSERT INTO fumigation_order (silo_id, request_id, order_no, window_start, window_end,"
105	                            + " synthetic_agent, plan_version, safety_threshold, status, fingerprint, version,"
106	                            + " created_at)"
107	                            + " VALUES (?, ?, NULL, ?, ?, ?, 1, ?, 'PENDING_APPROVAL', ?, 1, ?)",
108	                    siloId, request.requestId(), utc(request.windowStart()),
109	                    utc(request.windowEnd()), request.syntheticAgent(),
110	                    request.safetyThreshold(), fingerprint, utc(Instant.now()));
111	        } catch (DuplicateKeyException duplicate) {
112	            OrderRow row = findOrderByColumn("request_id", request.requestId()).orElseThrow(() -> duplicate);
113	            return replayOrConflict(row, fingerprint);
114	        }
115	        String orderNo = String.format("FUM-%08d", orderId);
116	        jdbc.update("UPDATE fumigation_order SET order_no = ? WHERE id = ?", orderNo, orderId);
117	        return toView(findOrderById(orderId).orElseThrow(), List.of(), false);
118	    }
119	
120	    /**
121	     * 熏蒸审批：两名不同审批人各批准一次；expectedVersion 乐观锁，
122	     * 第二名审批后状态转 APPROVED；同一审批人重复批准业务拒绝（失败不占键）。
123	     */
124	    @Transactional
125	    public FumigationView approve(long orderId, ApproveFumigationRequest request) {
126	        String fingerprint = Fingerprints.structured(request.requestId(), orderId,
127	                request.expectedVersion(), request.approver());
128	
129	        Optional<ApprovalRow> existingApproval = findApprovalByRequestId(request.requestId());
130	        if (existingApproval.isPresent()) {
131	            ApprovalRow row = existingApproval.get();
132	            if (row.fumigationId() != orderId) {
133	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
134	                        "requestId 已用于其他熏蒸单: " + request.requestId());
135	            }
136	            if (!row.fingerprint().equals(fingerprint)) {
137	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
138	                        "requestId 已存在但业务字段不一致: " + request.requestId());
139	            }
140	            return toView(findOrderById(orderId).orElseThrow(
141	                    () -> ApiException.notFound("FUMIGATION_NOT_FOUND", "熏蒸单不存在: " + orderId)),
142	                    findApprovers(orderId), true);
143	        }
144	
145	        OrderRow order = lockOrder(orderId);
146	        Optional<ApprovalRow> recheckedApproval = findApprovalByRequestId(request.requestId());
147	        if (recheckedApproval.isPresent()) {
148	            ApprovalRow row = recheckedApproval.get();
149	            if (row.fumigationId() != orderId) {
150	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
151	                        "requestId 已用于其他熏蒸单: " + request.requestId());
152	            }
153	            if (!row.fingerprint().equals(fingerprint)) {
154	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
155	                        "requestId 已存在但业务字段不一致: " + request.requestId());
156	            }
157	            return toView(order, findApprovers(orderId), true);
158	        }
159	        if (order.status() != FumigationStatus.PENDING_APPROVAL) {
160	            throw ApiException.unprocessable("INVALID_ORDER_STATE",
161	                    "仅待审批熏蒸单可审批，当前: " + order.status());
162	        }
163	        if (order.version() != request.expectedVersion()) {
164	            throw ApiException.conflict("VERSION_CONFLICT",
165	                    "期望版本 " + request.expectedVersion() + " 与当前版本 " + order.version() + " 不一致");
166	        }
167	
168	        try {
169	            siloService.insert(
170	                    "INSERT INTO fumigation_approval (fumigation_id, approver, request_id, expected_version,"
171	                            + " fingerprint, created_at) VALUES (?, ?, ?, ?, ?, ?)",
172	                    orderId, request.approver(), request.requestId(),
173	                    request.expectedVersion(), fingerprint, utc(Instant.now()));
174	        } catch (DuplicateKeyException duplicate) {
175	            // 同一审批人重复批准属于业务拒绝；事务回滚，requestId 不占键
176	            throw ApiException.unprocessable("APPROVER_DUPLICATED",
177	                    "同一审批人不可重复批准: " + request.approver());
178	        }
179	
180	        List<String> approvers = findApprovers(orderId);
181	        FumigationStatus newStatus = approvers.size() >= 2
182	                ? FumigationStatus.APPROVED : FumigationStatus.PENDING_APPROVAL;
183	        jdbc.update("UPDATE fumigation_order SET status = ?, version = version + 1 WHERE id = ?",
184	                newStatus.name(), orderId);
185	        return toView(findOrderById(orderId).orElseThrow(), approvers, false);
186	    }
187	
188	    /**
189	     * 实际开始：持仓锁后再查无执行中普通通风；开始时刻须落在 UTC 作业窗内；
190	     * 原子锁仓（粮仓转 FUMIGATING）、冻结方案版本，禁止人员进入与普通通风。
191	     */
192	    @Transactional
193	    public FumigationView start(long orderId, StartFumigationRequest request) {
194	        String fingerprint = Fingerprints.structured(request.requestId(), orderId,
195	                request.expectedVersion(), request.startedAt());
196	
197	        OrderRow order = lockOrder(orderId);
198	        if (order.startRequestId() != null) {
199	            return replayAction(order, order.startRequestId(), order.startFingerprint(),
200	                    fingerprint, request.requestId());
201	        }
202	        if (order.status() != FumigationStatus.APPROVED) {
203	            throw ApiException.unprocessable("INVALID_ORDER_STATE",
204	                    "仅已双审批熏蒸单可开始，当前: " + order.status());
205	        }
206	        if (order.version() != request.expectedVersion()) {
207	            throw ApiException.conflict("VERSION_CONFLICT",
208	                    "期望版本 " + request.expectedVersion() + " 与当前版本 " + order.version() + " 不一致");
209	        }
210	        if (request.startedAt().isBefore(order.windowStart())
211	                || !request.startedAt().isBefore(order.windowEnd())) {
212	            throw ApiException.unprocessable("START_OUTSIDE_WINDOW", "实际开始时刻必须位于作业窗 [起点, 终点) 内");
213	        }
214	
215	        // 锁仓行并再查执行中普通通风：熏蒸与通风不得各自放行
216	        List<SiloStatus> rows = jdbc.query("SELECT status FROM silo WHERE id = ? FOR UPDATE",
217	                (rs, rowNum) -> SiloStatus.valueOf(rs.getString("status")), order.siloId());
218	        if (rows.isEmpty()) {
219	            throw ApiException.notFound("SILO_NOT_FOUND", "粮仓不存在: " + order.siloId());
220	        }
221	        SiloStatus siloStatus = rows.get(0);
222	        if (siloStatus == SiloStatus.FUMIGATING || siloStatus == SiloStatus.AERATING) {
223	            throw ApiException.unprocessable("FUMIGATION_ALREADY_ACTIVE", "粮仓已被另一熏蒸作业锁定，禁止开始");
224	        }
225	        if (siloStatus == SiloStatus.ARCHIVED) {
226	            throw ApiException.unprocessable("SILO_ARCHIVED", "粮仓已归档，禁止开始熏蒸");
227	        }
228	        Integer executingVentilation = jdbc.queryForObject(
229	                "SELECT COUNT(*) FROM ventilation_job WHERE silo_id = ? AND status = 'EXECUTING'",
230	                Integer.class, order.siloId());
231	        if (executingVentilation != null && executingVentilation > 0) {
232	            throw ApiException.unprocessable("VENTILATION_EXECUTING", "存在执行中的普通通风，禁止开始熏蒸");
233	        }
234	
235	        jdbc.update("UPDATE fumigation_order SET status = 'FUMIGATING', frozen_plan_version = plan_version,"
236	                        + " started_at = ?, start_request_id = ?, start_fingerprint = ?, version = version + 1"
237	                        + " WHERE id = ?",
238	                utc(request.startedAt()), request.requestId(), fingerprint, orderId);
239	        jdbc.update("UPDATE silo SET status = 'FUMIGATING' WHERE id = ?", order.siloId());
240	        return toView(findOrderById(orderId).orElseThrow(), findApprovers(orderId), false);
241	    }
242	
243	    /**
244	     * 结束熏蒸转散气：原子绑定一台空闲风机（沿用风机唯一资源规则，占用失败整体回滚），
245	     * 粮仓与熏蒸单转散气态。
246	     */
247	    @Transactional
248	    public FumigationView beginAeration(long orderId, BeginAerationRequest request) {
249	        String fingerprint = Fingerprints.structured(request.requestId(), orderId,
250	                request.expectedVersion(), request.fanId(), request.aerationStartedAt());
251	
252	        OrderRow order = lockOrder(orderId);
253	        if (order.aerationRequestId() != null) {
254	            return replayAction(order, order.aerationRequestId(), order.aerationFingerprint(),
255	                    fingerprint, request.requestId());
256	        }
257	        if (order.status() != FumigationStatus.FUMIGATING) {
258	            throw ApiException.unprocessable("INVALID_ORDER_STATE",
259	                    "仅熏蒸中作业单可转散气，当前: " + order.status());
260	        }
261	        if (order.version() != request.expectedVersion()) {
262	            throw ApiException.conflict("VERSION_CONFLICT",
263	                    "期望版本 " + request.expectedVersion() + " 与当前版本 " + order.version() + " 不一致");
264	        }
265	        if (request.aerationStartedAt().isBefore(order.startedAt())) {
266	            throw ApiException.unprocessable("INVALID_AERATION_TIME", "散气开始时刻不得早于熏蒸开始时刻");
267	        }
268	        siloService.getFan(request.fanId());
269	
270	        int locked = jdbc.update(
271	                "UPDATE fan SET status = 'LOCKED', locked_fumigation_id = ?"
272	                        + " WHERE id = ? AND status = 'IDLE' AND locked_job_id IS NULL"
273	                        + " AND locked_fumigation_id IS NULL",
274	                orderId, request.fanId());
275	        if (locked == 0) {
276	            throw ApiException.conflict("FAN_BUSY", "风机已被占用: " + request.fanId());
277	        }
278	
279	        jdbc.update("UPDATE fumigation_order SET status = 'AERATING', fan_id = ?,"
280	                        + " aeration_started_at = ?, aeration_request_id = ?, aeration_fingerprint = ?,"
281	                        + " version = version + 1 WHERE id = ?",
282	                request.fanId(), utc(request.aerationStartedAt()), request.requestId(),
283	                fingerprint, orderId);
284	        jdbc.update("UPDATE silo SET status = 'AERATING' WHERE id = ?", order.siloId());
285	        return toView(findOrderById(orderId).orElseThrow(), findApprovers(orderId), false);
286	    }
287	
288	    /**
289	     * 散气合成气体采样：单号内序号唯一、采样时刻严格递增、浓度为有限非负小数；
290	     * 正常采样推动熏蒸单版本 +1；解除后读数只记迟到（late=TRUE），不改版本与冻结证据。
291	     */
292	    @Transactional
293	    public GasReadingView ingestGasReading(long orderId, GasReadingRequest request) {
294	        if (request.seqNo() < 1) {
295	            throw ApiException.badRequest("INVALID_SEQ_NO", "采样序号必须为正整数");
296	        }
297	        if (request.concentration().signum() < 0) {
298	            throw ApiException.badRequest("INVALID_CONCENTRATION", "合成气体浓度必须为有限非负小数");
299	        }
300	        String fingerprint = Fingerprints.structured(request.requestId(), orderId,
301	                request.expectedVersion(), request.seqNo(),
302	                request.concentration().stripTrailingZeros().toPlainString(), request.measuredAt());
303	
304	        Optional<ReadingRow> existing = findGasReadingByRequestId(request.requestId());
305	        if (existing.isPresent()) {
306	            ReadingRow row = existing.get();
307	            if (row.fumigationId() != orderId) {
308	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
309	                        "requestId 已用于其他熏蒸单: " + request.requestId());
310	            }
311	            if (!row.fingerprint().equals(fingerprint)) {
312	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
313	                        "requestId 已存在但业务字段不一致: " + request.requestId());
314	            }
315	            return toReadingView(row, true);
316	        }
317	
318	        OrderRow order = lockOrder(orderId);
319	        Optional<ReadingRow> rechecked = findGasReadingByRequestId(request.requestId());
320	        if (rechecked.isPresent()) {
321	            ReadingRow row = rechecked.get();
322	            if (row.fumigationId() != orderId) {
323	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
324	                        "requestId 已用于其他熏蒸单: " + request.requestId());
325	            }
326	            if (!row.fingerprint().equals(fingerprint)) {
327	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
328	                        "requestId 已存在但业务字段不一致: " + request.requestId());
329	            }
330	            return toReadingView(row, true);
331	        }
332	
333	        boolean late = order.status() == FumigationStatus.RELEASED;
334	        if (!late && order.status() != FumigationStatus.AERATING) {
335	            throw ApiException.unprocessable("INVALID_ORDER_STATE",
336	                    "仅散气中熏蒸单可采样，当前: " + order.status());
337	        }
338	        if (!late && order.version() != request.expectedVersion()) {
339	            throw ApiException.conflict("VERSION_CONFLICT",
340	                    "期望版本 " + request.expectedVersion() + " 与当前版本 " + order.version() + " 不一致");
341	        }
342	        if (!late) {
343	            Optional<Instant> latestMeasuredAt = jdbc.query(
344	                            "SELECT MAX(measured_at) FROM gas_reading WHERE fumigation_id = ? AND late = FALSE",
345	                            (rs, rowNum) -> Optional.ofNullable(rs.getTimestamp(1))
346	                                    .map(ts -> ts.toLocalDateTime().toInstant(ZoneOffset.UTC)),
347	                            orderId)
348	                    .stream().findFirst().orElse(Optional.empty());
349	            if (latestMeasuredAt.isPresent() && !request.measuredAt().isAfter(latestMeasuredAt.get())) {
350	                throw ApiException.unprocessable("READING_TIME_NOT_INCREASING",
351	                        "采样时刻必须在同单号内严格递增");
352	            }
353	        }
354	
355	        try {
356	            long readingId = siloService.insert(
357	                    "INSERT INTO gas_reading (fumigation_id, request_id, seq_no, concentration, measured_at,"
358	                            + " late, fingerprint, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
359	                    orderId, request.requestId(), request.seqNo(), request.concentration(),
360	                    utc(request.measuredAt()), late, fingerprint, utc(Instant.now()));
361	            if (!late) {
362	                jdbc.update("UPDATE fumigation_order SET version = version + 1 WHERE id = ?", orderId);
363	            }
364	            return toReadingView(findGasReadingById(readingId).orElseThrow(), false);
365	        } catch (DuplicateKeyException duplicate) {
366	            ReadingRow row = findGasReadingByRequestId(request.requestId()).orElse(null);
367	            if (row != null) {
368	                if (!row.fingerprint().equals(fingerprint)) {
369	                    throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
370	                            "requestId 已存在但业务字段不一致: " + request.requestId());
371	                }
372	                return toReadingView(row, true);
373	            }
374	            throw ApiException.unprocessable("SEQ_NO_DUPLICATED",
375	                    "采样序号在同单号内必须唯一: " + request.seqNo());
376	        }
377	    }
378	
379	    /**
380	     * 双复核解除：两名不同复核人；持锁重查最新版本与读数，最后三点必须序号连续、
381	     * 浓度均 ≤ 安全阈值（恰等合法）、首末间隔 ≥ 30 分钟（恰等合法），越限或缺号不放行；
382	     * 任一失败均不释放仓锁与风机；成功则同事务原子结束散气、释放仓锁与风机。
383	     */
384	    @Transactional
385	    public ReleaseView release(long orderId, ReleaseFumigationRequest request) {
386	        String fingerprint = Fingerprints.structured(request.requestId(), orderId,
387	                request.expectedVersion(), Fingerprints.stringList(request.reviewers()));
388	
389	        Optional<ReleaseRow> existing = findReleaseByRequestId(request.requestId());
390	        if (existing.isPresent()) {
391	            ReleaseRow row = existing.get();
392	            if (row.fumigationId() != orderId) {
393	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
394	                        "requestId 已用于其他熏蒸单: " + request.requestId());
395	            }
396	            if (!row.fingerprint().equals(fingerprint)) {
397	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
398	                        "requestId 已存在但业务字段不一致: " + request.requestId());
399	            }
400	            return toReleaseView(row, true);
401	        }
402	
403	        OrderRow order = lockOrder(orderId);
404	        Optional<ReleaseRow> rechecked = findReleaseByRequestId(request.requestId());
405	        if (rechecked.isPresent()) {
406	            ReleaseRow row = rechecked.get();
407	            if (row.fumigationId() != orderId) {
408	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
409	                        "requestId 已用于其他熏蒸单: " + request.requestId());
410	            }
411	            if (!row.fingerprint().equals(fingerprint)) {
412	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
413	                        "requestId 已存在但业务字段不一致: " + request.requestId());
414	            }
415	            return toReleaseView(row, true);
416	        }
417	        if (request.reviewers() == null || request.reviewers().size() != 2) {
418	            throw ApiException.badRequest("INVALID_REVIEWERS", "解除必须恰好提供两名复核人");
419	        }
420	        if (order.status() != FumigationStatus.AERATING) {
421	            throw ApiException.unprocessable("INVALID_ORDER_STATE",
422	                    "仅散气中熏蒸单可解除，当前: " + order.status());
423	        }
424	        if (order.version() != request.expectedVersion()) {
425	            throw ApiException.conflict("VERSION_CONFLICT",
426	                    "期望版本 " + request.expectedVersion() + " 与当前版本 " + order.version() + " 不一致");
427	        }
428	        if (order.frozenPlanVersion() == null) {
429	            throw ApiException.unprocessable("PLAN_NOT_FROZEN", "方案版本未冻结，禁止解除");
430	        }
431	        if (request.reviewers().get(0).equals(request.reviewers().get(1))) {
432	            throw ApiException.unprocessable("REVIEWERS_MUST_DIFFER", "两名复核人必须不同");
433	        }
434	
435	        SafeWindow window = evaluateLatestReadings(order);
436	
437	        long releaseId;
438	        try {
439	            releaseId = siloService.insert(
440	                    "INSERT INTO fumigation_release (fumigation_id, request_id, expected_version, reviewer1,"
441	                            + " reviewer2, checked_version, last_seq_no, first_seq_no, fingerprint, created_at)"
442	                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
443	                    orderId, request.requestId(), request.expectedVersion(),
444	                    request.reviewers().get(0), request.reviewers().get(1),
445	                    order.version(), window.last().seqNo(), window.first().seqNo(), fingerprint,
446	                    utc(Instant.now()));
447	        } catch (DuplicateKeyException duplicate) {
448	            // 并发解除：同 requestId 重放；同单异 requestId 判冲突（只有一个解除可成功）
449	            ReleaseRow row = findReleaseByRequestId(request.requestId()).orElse(null);
450	            if (row != null) {
451	                if (!row.fingerprint().equals(fingerprint)) {
452	                    throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
453	                            "requestId 已存在但业务字段不一致: " + request.requestId());
454	                }
455	                return toReleaseView(row, true);
456	            }
457	            throw ApiException.conflict("RELEASE_ALREADY_DONE",
458	                    "该熏蒸单已被并发解除，资源释放以首次结果为准");
459	        }
460	
461	        // 原子结束散气：熏蒸单终态、仓锁释放回日常监测、风机释放
462	        jdbc.update("UPDATE fumigation_order SET status = 'RELEASED', released_at = ?,"
463	                + " version = version + 1 WHERE id = ?", utc(Instant.now()), orderId);
464	        jdbc.update("UPDATE fan SET status = 'IDLE', locked_fumigation_id = NULL"
465	                + " WHERE locked_fumigation_id = ?", orderId);
466	        jdbc.update("UPDATE silo SET status = 'MONITORING' WHERE id = ?", order.siloId());
467	        return toReleaseView(findReleaseById(releaseId).orElseThrow(), false);
468	    }
469	
470	    /** 查询熏蒸单（含审批人列表），不存在 404。 */
471	    public FumigationView getOrder(long orderId) {
472	        OrderRow order = findOrderById(orderId).orElseThrow(
473	                () -> ApiException.notFound("FUMIGATION_NOT_FOUND", "熏蒸单不存在: " + orderId));
474	        return toView(order, findApprovers(orderId), false);
475	    }
