477	    /** 查询熏蒸单全部气体读数（按序号排序，含解除后迟到读数）。 */
478	    public List<GasReadingView> readings(long orderId) {
479	        getOrder(orderId);
480	        return jdbc.query("SELECT * FROM gas_reading WHERE fumigation_id = ? ORDER BY seq_no, id",
481	                FumigationService::mapGasReading, orderId).stream()
482	                .map(row -> toReadingView(row, false)).toList();
483	    }
