485	    /** 查询解除双复核记录，不存在 404。 */
486	    public ReleaseView getRelease(long orderId) {
487	        return toReleaseView(findReleaseByOrderId(orderId).orElseThrow(
488	                () -> ApiException.notFound("RELEASE_NOT_FOUND", "解除记录不存在: " + orderId)), false);
489	    }
490	
491	    /**
492	     * 评估最新三点：取非迟到读数按序号倒序前三点，要求三点齐备且序号连续（缺号不放行）、
493	     * 三点浓度均不超过安全阈值（越限打断，不放行）、首末时刻间隔 ≥ 30 分钟。
494	     */
495	    private SafeWindow evaluateLatestReadings(OrderRow order) {
496	        List<ReadingRow> latestDesc = jdbc.query(
497	                "SELECT * FROM gas_reading WHERE fumigation_id = ? AND late = FALSE"
498	                        + " ORDER BY seq_no DESC, id DESC LIMIT ?",
499	                FumigationService::mapGasReading, order.id(), SAFE_RUN_LENGTH);
500	        if (latestDesc.size() < SAFE_RUN_LENGTH) {
501	            throw ApiException.unprocessable("GAS_SEQUENCE_INCOMPLETE",
502	                    "安全采样点不足三点，缺号不视为安全，禁止解除");
503	        }
504	        List<ReadingRow> window = List.of(latestDesc.get(2), latestDesc.get(1), latestDesc.get(0));
505	        ReadingRow first = window.get(0);
506	        ReadingRow middle = window.get(1);
507	        ReadingRow last = window.get(2);
508	        if (last.seqNo() - first.seqNo() != SAFE_RUN_LENGTH - 1
509	                || middle.seqNo() != first.seqNo() + 1) {
510	            throw ApiException.unprocessable("GAS_SEQUENCE_INCOMPLETE",
511	                    "最新三点序号不连续，缺号不视为安全，禁止解除");
512	        }
513	        for (ReadingRow reading : window) {
514	            if (reading.concentration().compareTo(order.safetyThreshold()) > 0) {
515	                throw ApiException.unprocessable("GAS_NOT_SAFE",
516	                        "连续三点中存在超过安全阈值的读数，禁止解除");
517	            }
518	        }
519	        Duration gap = Duration.between(first.measuredAt(), last.measuredAt());
520	        if (gap.compareTo(MIN_FIRST_LAST_GAP) < 0) {
521	            throw ApiException.unprocessable("AERATION_DURATION_SHORT",
522	                    "安全三点首末间隔不足30分钟，禁止解除");
523	        }
524	        return new SafeWindow(first, last);
525	    }
526	
527	    private void assertNoWindowOverlap(long siloId, Instant windowStart, Instant windowEnd) {
528	        // 普通通风窗以 Asia/Shanghai 本地墙钟时间存储；熏蒸窗为 UTC，需转换到同一时间轴再比较
529	        ZoneId zone = ZoneId.of("Asia/Shanghai");
530	        LocalDateTime ventilationStart = LocalDateTime.ofInstant(windowStart, zone);
531	        LocalDateTime ventilationEnd = LocalDateTime.ofInstant(windowEnd, zone);
532	        Integer ventilationOverlaps = jdbc.queryForObject(
533	                "SELECT COUNT(*) FROM ventilation_job WHERE silo_id = ? AND window_start < ? AND ? < window_end",
534	                Integer.class, siloId, ventilationEnd, ventilationStart);
535	        if (ventilationOverlaps != null && ventilationOverlaps > 0) {
536	            throw ApiException.unprocessable("WINDOW_CONFLICT", "熏蒸作业窗与既有普通通风窗重叠（端点相接不冲突）");
537	        }
538	        Integer fumigationOverlaps = jdbc.queryForObject(
539	                "SELECT COUNT(*) FROM fumigation_order WHERE silo_id = ? AND status <> 'RELEASED'"
540	                        + " AND window_start < ? AND ? < window_end",
541	                Integer.class, siloId, utc(windowEnd), utc(windowStart));
542	        if (fumigationOverlaps != null && fumigationOverlaps > 0) {
543	            throw ApiException.unprocessable("WINDOW_CONFLICT", "熏蒸作业窗与既有未终结熏蒸窗重叠（端点相接不冲突）");
544	        }
545	    }
