569	    private FumigationView replayOrConflict(OrderRow row, String fingerprint) {
570	        if (!row.fingerprint().equals(fingerprint)) {
571	            throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
572	                    "requestId 已存在但业务字段不一致: " + row.requestId());
