577	    /**
578	     * 状态推进动作（开始/转散气）幂等重放：同 requestId 且指纹一致返回首次冻结结果；
579	     * 同键异参 409；异键重复推进 409（动作已完成）。
580	     */
581	    private FumigationView replayAction(OrderRow order, String storedRequestId, String storedFingerprint,
582	                                        String fingerprint, String requestId) {
583	        if (!storedRequestId.equals(requestId)) {
584	            throw ApiException.conflict("ACTION_ALREADY_DONE",
585	                    "该状态推进动作已使用其他 requestId 完成: " + storedRequestId);
586	        }
587	        if (!storedFingerprint.equals(fingerprint)) {
588	            throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
589	                    "requestId 已存在但业务字段不一致: " + requestId);
590	        }
591	        return toView(findOrderById(order.id()).orElseThrow(), findApprovers(order.id()), true);
592	    }
