640	    private static OrderRow mapOrder(ResultSet rs, int rowNum) throws SQLException {
641	        return new OrderRow(
642	                rs.getLong("id"),
643	                rs.getLong("silo_id"),
644	                rs.getString("request_id"),
645	                rs.getString("order_no"),
646	                toInstant(rs, "window_start"),
647	                toInstant(rs, "window_end"),
648	                rs.getString("synthetic_agent"),
649	                rs.getInt("plan_version"),
650	                (Integer) rs.getObject("frozen_plan_version"),
651	                rs.getBigDecimal("safety_threshold"),
652	                FumigationStatus.valueOf(rs.getString("status")),
653	                (Long) rs.getObject("fan_id"),
654	                toInstant(rs, "started_at"),
655	                toInstant(rs, "aeration_started_at"),
656	                toInstant(rs, "released_at"),
657	                rs.getString("fingerprint"),
658	                rs.getString("start_request_id"),
659	                rs.getString("start_fingerprint"),
660	                rs.getString("aeration_request_id"),
