672	        return new ReleaseRow(rs.getLong("id"), rs.getLong("fumigation_id"),
673	                rs.getString("request_id"), rs.getInt("expected_version"),
674	                rs.getString("reviewer1"), rs.getString("reviewer2"),
675	                rs.getInt("checked_version"), rs.getInt("last_seq_no"), rs.getInt("first_seq_no"),
