679	    /** Instant → 裸 UTC LocalDateTime，存入无时区 TIMESTAMP，不依赖 JVM 默认时区。 */
680	    private static LocalDateTime utc(Instant instant) {
681	        return LocalDateTime.ofInstant(instant, ZoneOffset.UTC);
682	    }
683	
684	    /** 无时区 TIMESTAMP（裸 UTC 墙钟）→ Instant。 */
685	    private static Instant toInstant(ResultSet rs, String column) throws SQLException {
686	        Timestamp timestamp = rs.getTimestamp(column);
687	        return timestamp == null ? null : timestamp.toLocalDateTime().toInstant(ZoneOffset.UTC);
688	    }
