690	    private static FumigationView toView(OrderRow row, List<String> approvers, boolean replayed) {
691	        return new FumigationView(row.id(), row.siloId(), row.orderNo(), row.windowStart(),
692	                row.windowEnd(), row.syntheticAgent(), row.planVersion(), row.frozenPlanVersion(),
693	                row.safetyThreshold(), row.status(), row.fanId(), row.startedAt(),
