package com.example.starter.dto;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDateTime;
import java.util.List;

import com.example.starter.model.FumigationStatus;
import com.example.starter.model.JobStatus;
import com.example.starter.model.RecheckDecision;
import com.example.starter.model.SiloStatus;
import com.example.starter.model.VentilationPurpose;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 粮情测控服务请求/响应对象集合。
 */
public final class GrainDtos {

    private GrainDtos() {
    }

    /** 创建粮仓请求；安全温度单位℃，平衡湿度单位%RH。 */
    public record CreateSiloRequest(
            @NotBlank String code,
            @NotBlank String name,
            @NotNull BigDecimal safeTemperature,
            @NotNull BigDecimal equilibriumHumidity) {
    }

    /** 粮仓视图。 */
    public record SiloView(
            long id,
            String code,
            String name,
            BigDecimal safeTemperature,
            BigDecimal equilibriumHumidity,
            SiloStatus status) {
    }

    /** 创建风机请求。 */
    public record CreateFanRequest(
            @NotBlank String code,
            @NotBlank String name) {
    }

    /** 风机视图。 */
    public record FanView(
            long id,
            String code,
            String name,
            String status,
            Long lockedJobId) {
    }

    /**
     * 温湿度上报请求；requestId 幂等，指纹覆盖 requestId 与全部业务字段。
     * 温度单位℃，湿度单位%RH，measuredAt 为 Asia/Shanghai 本地时间。
     */
    public record ReadingRequest(
            @NotBlank String requestId,
            @NotNull Integer pointNo,
            @NotNull BigDecimal temperature,
            BigDecimal outsideHumidity,
            @NotNull LocalDateTime measuredAt) {
    }

    /**
     * 温湿度上报结果：NORMAL 正常（含恰等安全温度）、ALARM 已告警、LATE_RECORDED 归档后迟到仅记事件。
     */
    public record ReadingResponse(
            String result,
            Long alarmId,
            SiloStatus siloStatus,
            boolean replayed) {
    }

    /**
     * 通风作业下达请求；requestId 幂等。作业窗为半开区间 [windowStart, windowEnd)。
     */
    public record CreateJobRequest(
            @NotBlank String requestId,
            @NotNull Long fanId,
            @NotNull VentilationPurpose purpose,
            @NotNull LocalDateTime windowStart,
            @NotNull LocalDateTime windowEnd,
            @NotNull BigDecimal outsideHumidity) {
    }

    /** 通风作业视图。 */
    public record JobView(
            long id,
            long siloId,
            long fanId,
            VentilationPurpose purpose,
            LocalDateTime windowStart,
            LocalDateTime windowEnd,
            BigDecimal outsideHumidity,
            int roundNo,
            JobStatus status,
            boolean replayed) {
    }

    /**
     * 复测请求；梯度与限值单位℃，超过限值判超标，恰等判合格。
     */
    public record RecheckRequest(
            @NotBlank String requestId,
            @NotNull BigDecimal gradient,
            @NotNull BigDecimal gradientLimit,
            @NotNull LocalDateTime measuredAt) {
    }

    /** 复测视图。 */
    public record RecheckView(
            long id,
            long jobId,
            long siloId,
            int roundNo,
            BigDecimal gradient,
            BigDecimal gradientLimit,
            boolean exceeded,
            RecheckDecision decision,
            boolean replayed) {
    }

    /** 温度曲线点。 */
    public record TemperaturePoint(
            int pointNo,
            BigDecimal temperature,
            LocalDateTime measuredAt) {
    }

    /** 迟到事件视图。 */
    public record LateEventView(
            long id,
            long siloId,
            String requestId,
            String eventType,
            String payload,
            LocalDateTime recordedAt) {
    }

    /**
     * 熏蒸申请请求；作业窗为 UTC 半开区间 [windowStart, windowEnd)，端点相接可共存。
     * syntheticAgent 仅为合成方案标识，不计算真实药剂剂量；safetyThreshold 为合成安全浓度，单位 ppm。
     */
    public record ApplyFumigationRequest(
            @NotBlank String requestId,
            @NotNull Instant windowStart,
            @NotNull Instant windowEnd,
            @NotBlank String syntheticAgent,
            @NotNull BigDecimal safetyThreshold) {
    }

    /** 熏蒸审批请求：expectedVersion 为客户端期望版本；两名审批人须不同，各批准一次。 */
    public record ApproveFumigationRequest(
            @NotBlank String requestId,
            @NotNull Integer expectedVersion,
            @NotBlank String approver) {
    }

    /** 熏蒸实际开始请求：startedAt 为 UTC 精确时刻，开始时再查无执行中普通通风。 */
    public record StartFumigationRequest(
            @NotBlank String requestId,
            @NotNull Integer expectedVersion,
            @NotNull Instant startedAt) {
    }

    /** 结束熏蒸转散气请求：绑定一台空闲风机，aerationStartedAt 为 UTC 精确时刻。 */
    public record BeginAerationRequest(
            @NotBlank String requestId,
            @NotNull Integer expectedVersion,
            @NotNull Long fanId,
            @NotNull Instant aerationStartedAt) {
    }

    /** 散气合成气体采样请求：seqNo 单号内唯一且时刻严格递增；concentration 单位 ppm，有限非负小数。 */
    public record GasReadingRequest(
            @NotBlank String requestId,
            @NotNull Integer expectedVersion,
            @NotNull Integer seqNo,
            @NotNull BigDecimal concentration,
            @NotNull Instant measuredAt) {
    }

    /** 解除锁仓请求：两名不同复核人共同确认，须携带期望版本，确认时重查最新读数与版本。 */
    public record ReleaseFumigationRequest(
            @NotBlank String requestId,
            @NotNull Integer expectedVersion,
            @NotNull @jakarta.validation.constraints.Size(min = 2, max = 2)
            List<@NotBlank String> reviewers) {
    }

    /** 熏蒸单视图；时间均为 UTC。 */
    public record FumigationView(
            long id,
            long siloId,
            String orderNo,
            Instant windowStart,
            Instant windowEnd,
            String syntheticAgent,
            int planVersion,
            Integer frozenPlanVersion,
            BigDecimal safetyThreshold,
            FumigationStatus status,
            Long fanId,
            Instant startedAt,
            Instant aerationStartedAt,
            Instant releasedAt,
            int version,
            List<String> approvers,
            boolean replayed) {
    }

    /** 气体读数视图；late=TRUE 表示解除后的迟到读数，不参与安全判定。 */
    public record GasReadingView(
            long id,
            long fumigationId,
            int seqNo,
            BigDecimal concentration,
            Instant measuredAt,
            boolean late,
            boolean replayed) {
    }

    /** 解除双复核视图。 */
    public record ReleaseView(
            long id,
            long fumigationId,
            int checkedVersion,
            int lastSeqNo,
            int firstSeqNo,
            List<String> reviewers,
            Instant releasedAt,
            boolean replayed) {
    }
}

content.thinking:
ReleaseView constructor changed — FumigationService.toReleaseView must be updated. That's part of step 3. Let me first do a compile check to confirm the only breakage is in the service (expected), then implement the service.

Actually per the small-step guidance: build now to confirm skeleton state. The build will fail in FumigationService.toReleaseView. That's fine — I'll implement the service changes now, which is the next step anyway. Let me write the service changes in one go since they're one file.

Service changes:

1. `ingestGasReading`: after locking order and determining not-late... actually the check "受控单旧单点采样入口拒绝" should happen before processing. Where? After lockOrder and idempotency recheck, before state checks. If roster exists for the order → throw 422 MULTI_POINT_REQUIRED. Should this apply to late readings too? "受控单旧单点采样入口拒绝" — yes, always reject for controlled orders. Put the check right after the idempotency recheck (before late determination).

Wait, but idempotent replay: if a reading was recorded before the roster was registered (order was non-controlled, then roster registered — possible? Roster registration allowed in PENDING_APPROVAL/APPROVED/FUMIGATING; gas readings only in AERATING. So readings can only exist after aeration, and roster must be registered before aeration. So an order with gas_reading rows can never become controlled. Good — no conflict. But replay check happens first anyway, fine.)

2. `registerRoster(orderId, request)`:
   - fingerprint: structured(requestId, orderId, expectedVersion, stringList(sorted points))
   - idempotency: find roster by request_id → replay/conflict (check fumigation_id match + fingerprint).
   - lockOrder; recheck idempotency.
   - validate: points size 2..10 (also bean validation), distinct (else 400 INVALID_POINTS).
   - status must be PENDING_APPROVAL/APPROVED/FUMIGATING （散气前） else 422 INVALID_ORDER_STATE.
   - no existing roster (else 422 ROSTER_ALREADY_EXISTS).
   - version check → 409.
   - insert roster (roster_version 1) + points; order version+1.
   - return RosterView.

3. `addRosterPoints(orderId, request)`:
   - fingerprint: structured(requestId, orderId, expectedVersion, stringList(sorted new points))
   - idempotency by request_id.
   - lockOrder; recheck.
   - roster must exist (else 422 ROSTER_NOT_REGISTERED).
   - status != RELEASED (else 422 INVALID_ORDER_STATE).
   - version check.
   - validate new points: non-empty, distinct within request (400 INVALID_POINTS); none already in current roster (422 POINT_ALREADY_EXISTS); union size ≤ 10 (422 ROSTER_TOO_LARGE).
   - new roster row with roster_version = current+1, points = union (sorted for determinism).
   - order version+1.

4. `ingestGasFrame(orderId, request)`:
   - validate: seqNo ≥ 1 (400 INVALID_SEQ_NO); concentrations non-negative (400 INVALID_CONCENTRATION); readings non-empty; duplicate point codes in request → 400 INVALID_FRAME_POINTS.
   - fingerprint: structured(requestId, orderId, expectedVersion, seqNo, measuredAt, encoded sorted readings). Encode readings: for each (sorted by pointCode): pointCode + concentration.stripTrailingZeros().toPlainString(). Build a list of strings "code=conc" and use stringList.
   - idempotency by request_id → replay/conflict.
   - lockOrder; recheck idempotency.
   - roster must exist (else 422 ROSTER_NOT_REGISTERED "未启用多测点，使用单点采样入口").
   - late = status == RELEASED; if !late && status != AERATING → 422 INVALID_ORDER_STATE.
   - if !late: version check → 409.
   - point set must equal current roster exactly: missing → 422 FRAME_POINTS_MISMATCH （缺点）; unknown → 422 FRAME_POINTS_MISMATCH （未知点）. Compare sets.
   - if !late: measured_at strictly increasing vs max non-late frame measured_at → 422 FRAME_TIME_NOT_INCREASING.
   - compute max, safe = max <= threshold.
   - insert frame + points; if !late version+1.
   - DuplicateKeyException: request_id → replay/conflict; (fumigation_id, seq_no) → 422 SEQ_NO_DUPLICATED.

5. `release`: after existing checks (status AERATING, version, frozen plan, reviewers differ):
   - find current roster. If present → evaluate frames: latest 3 non-late frames of current roster_id; consecutive seq; all safe; gap ≥ 30min. checkedRosterVersion = roster_version. Else old evaluateLatestReadings; checkedRosterVersion = null.
