public GasSafetyView gasSafety(long orderId) {
    getOrder(orderId);
    RosterRow roster = currentRoster(orderId).orElseThrow(
            () -> ApiException.notFound("ROSTER_NOT_FOUND", "测点名单不存在: " + orderId));
    List<FrameRow> desc = jdbc.query(
            "SELECT * FROM gas_frame WHERE fumigation_id = ? AND roster_id = ? AND late = FALSE"
                    + " ORDER BY seq_no DESC, id DESC",
            FumigationService::mapFrame, order.id(), roster.id());
    // wait, need order id. getOrder returns view with id == orderId. Use orderId directly.
    int run = 0;
    Integer previousSeq = null;
    List<FrameRow> runFrames = new ArrayList<>();
    for (FrameRow frame : desc) {
        if (!frame.safe()) break;
        if (previousSeq != null && frame.seqNo() != previousSeq - 1) break;
        run++;
        runFrames.add(frame);
        previousSeq = frame.seqNo();
    }
    if (runFrames.isEmpty()) {
        return new GasSafetyView(orderId, roster.rosterVersion(), 0, null, null, null, null, null, false);
    }
    FrameRow last = runFrames.get(0);
    FrameRow first = runFrames.get(runFrames.size() - 1);
    Long gap = Duration.between(first.measuredAt(), last.measuredAt()).getSeconds();
    boolean releasable;
    if (runFrames.size() >= SAFE_RUN_LENGTH) {
        FrameRow third = runFrames.get(SAFE_RUN_LENGTH - 1);
        long gap3 = Duration.between(third.measuredAt(), last.measuredAt()).getSeconds();
        releasable = gap3 >= MIN_FIRST_LAST_GAP.getSeconds();
    } else {
        releasable = false;
    }
    return new GasSafetyView(orderId, roster.rosterVersion(), run, first.seqNo(), last.seqNo(),
            first.measuredAt(), last.measuredAt(), gap, releasable);
}
